 const earnedFeats=[...(background?.feat?[{name:background.feat,source:'Background'}]:[]),...(campaign.importedEarnedFeats??[]).filter(feat=>feat.level<=(c.level??1)).map(feat=>({name:feat.name,source:'Level '+feat.level}))];
 const subclass=subclassesForClass(identity.classId).find(entry=>entry.id===campaign.importedSubclassId&& (c.level??1)>=entry.unlockLevel);
 const spellcasting=spellcastingAtLevel(identity.classId,c.level??1);
 const castingAbility=identity.classId==='rogue'&&campaign.importedSubclassId==='rogue-arcane-trickster'?'int':spellcasting?.ability?.toLowerCase() as keyof typeof c.scores|undefined;
 const spellBonus=castingAbility!==undefined?c.proficiencyBonus+abilityModifier(c.scores[castingAbility]):undefined;
 const slots=[{rank:1,total:c.spellSlots?.level1??0,used:c.spellSlots?.usedLevel1??0},{rank:2,total:c.spellSlots?.level2??0,used:c.spellSlots?.usedLevel2??0},...[3,4,5,6,7,8,9].map(rank=>({rank,total:(c.spellSlots as Record<string,number>|undefined)?.[`level${rank}`]??0,used:(c.spellSlots as Record<string,number>|undefined)?.[`usedLevel${rank}`]??0}))].filter(slot=>slot.total>0);
