 const [hpGain,setHpGain]=useState(5),[subclassId,setSubclassId]=useState(''),[arcaneCantrips,setArcaneCantrips]=useState<string[]>([]),[arcaneSpells,setArcaneSpells]=useState<string[]>([]),[warlockInvocations,setWarlockInvocations]=useState<string[]>([]),[warlockSpell,setWarlockSpell]=useState(''),[wizardBook,setWizardBook]=useState<string[]>([]),[wizardPrepared,setWizardPrepared]=useState<string[]>([]),[wizardPortents,setWizardPortents]=useState<string[]>(['','']),[featPlan,setFeatPlan]=useState(''),[legacyApproved,setLegacyApproved]=useState(false),[firstASI,setFirstASI]=useState<Ability>('Dex'),[secondASI,setSecondASI]=useState<Ability>('Dex'),[featAbility,setFeatAbility]=useState<Ability>('Dex'),[skillProficiency,setSkillProficiency]=useState<Skill>('Acrobatics'),[skillExpertise,setSkillExpertise]=useState<Skill>('Acrobatics'),[rogueExpertise,setRogueExpertise]=useState<Skill[]>([]),[confirmed,setConfirmed]=useState(false),[error,setError]=useState(''),[xpAmount,setXpAmount]=useState(0),[xpReason,setXpReason]=useState('');
