 <section id="player-details" className="scroll-mt-36 rounded-lg border border-white/20 p-3 space-y-1" aria-label="Character details"><h3 className="font-semibold">Character details</h3><p>Background: {identity.backgroundId} · Lineage: {identity.lineageId??identity.speciesId}</p>{identity.pronouns&&<p>Pronouns: {identity.pronouns}</p>}{identity.appearance&&<p>Appearance: {identity.appearance}</p>}{identity.personality&&<p>Personality: {identity.personality}</p>}{identity.backstory&&<p>Backstory: {identity.backstory}</p>}</section>
